import{_ as s,l as i,o as e,c as n,v as t,p as d,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"保存点","description":"","frontmatter":{"title":"保存点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/savepoints.md","filePath":"cs/savepoints.md","lastUpdated":1789023840000}'),h={name:"cs/savepoints.md"};function A(_,a,E,m,u,T){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="保存点" tabindex="-1">保存点 <a class="header-anchor" href="#保存点" aria-label="Permalink to &quot;保存点&quot;">​</a></h1><div class="epigraph"><p>保存点在事务内部钉一截可回退的状态：撤销其后的更新，事务本身尚未结束，外层仍可提交。</p><footer>—— 据 Gray and Reuter, Transaction Processing；SQL 对 SAVEPOINT；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/stored-procedures">上一课</a>把多语句收进过程。本课不重讲 <code>CALL</code>。缺口是过程或长事务里<strong>局部失败</strong>：第三条语句违反约束，是否必须丢掉前两条已做的更新？全事务回滚太粗；每条自动提交又失去原子性。保存点给出事务内的嵌套撤销。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/acid">ACID</a> 的原子性以事务为边界。实际脚本是：尝试插入，失败则改另一条路径，成功路径上的前序写入仍要留下。保存点：<code>SAVEPOINT s</code> 记录当前撤销链位置；<code>ROLLBACK TO s</code> 撤销之后的更新与（实现相关的）锁，事务继续；<code>RELEASE</code> 丢掉该标记。缺口是嵌套恢复的语义，不是再定义 commit。</p><p>与子事务（nested transaction）文献对照：完整嵌套事务有独立提交可见性规则；SQL 保存点更弱，通常仍是同一事务、同一提交。本课按 SQL 保存点讲，不把 Moss 嵌套事务模型整套搬进主干。</p><p><span class="marginnote">Gray and Reuter 把 savepoint 当作长事务与过程错误恢复的原语。实现上它是日志里的标记：UNDO 走到该 LSN 为止，而不是走到事务头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>过程里：危险语句前设保存点，捕获约束错误则 <code>ROLLBACK TO</code>，改走分支。应用协议：批处理中单行失败不污染整批，但仍在一个提交里。注意：回滚到保存点后，其后获得的行锁是否释放因引擎而异，文档必须当合同读。</p><p>不能把保存点当成跨连接的会话魔法：连接断开，事务没了，保存点也没了。也不等于两阶段提交的子协调——跨资源仍是 <a href="/cs/two-pc">2PC</a>。</p>',10)),(e(),d(p,null,{default:o(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEG%5B%22BEGIN%22%5D%20--%3E%20SP%5B%22SAVEPOINT%20s%22%5D%0A%20%20SP%20--%3E%20DML%5B%22%E5%90%8E%E7%BB%AD%20DML%22%5D%0A%20%20DML%20--%3E%20RTS%5B%22ROLLBACK%20TO%20s%22%5D%0A%20%20DML%20--%3E%20COM%5B%22COMMIT%20%E6%95%B4%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20RTS%20--%3E%20MORE%5B%22%E4%BA%8B%E5%8A%A1%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>WAL：每条更新仍记日志；回滚到保存点通过 UNDO 补偿（ARIES 后课的 CLR 同源）。已刷盘的日志不会消失，只是逻辑上那些更新被补偿。并发：保存点不引入新隔离级别；可见性仍按事务快照或锁协议。</p><p>保存点深度有限制。循环里每轮新建保存点要释放，否则资源涨。触发器与保存点交错：触发器里回滚到外层保存点可能毁掉调用方预期，属于过程设计错误。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲模式迁移如何用事务包住 DDL——下一课。也不把保存点当业务「草稿箱」：长事务持锁，保存点减的是撤销粒度，不是锁范围的理论上限。</p><p>后课默认：需要语句级失败隔离时用保存点，需要全体成功或全体失败时不要拆保存点冒充多事务。模式演化下一课：约束与表结构的版本化变更。</p><p>原子性边界仍是事务。保存点是事务内部的 UNDO 游标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保存点允许事务内部分回滚，提交仍是一次。</li><li>实现依赖日志 UNDO；锁释放规则因引擎而异。</li><li>模式迁移下一课：DDL 与数据回填如何分步还不丢不变式。</li><li>出处：Gray and Reuter；SQL SAVEPOINT；Ramakrishnan and Gehrke。</li></ul>',9))])}const S=s(h,[["render",A]]);export{D as __pageData,S as default};
